								<td align="left" valign="middle">
									<b><a href="http://masslinemedia.com/smf/index.php?topic=2209.msg27414#msg27414">Re: (Rich) White People and Blue Scholars</a></b>
									<div class="smalltext">&#171; <b>Reply #3 on:</b> May 16, 2007, 10:38:42 am &#187;</div></td>
								<td align="right" valign="bottom" height="20" nowrap="nowrap" style="font-size: smaller;">
